  @protected
  void sse_encode_distortion_dto(DistortionDto self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case DistortionDto_None():
        sse_encode_i_32(0, serializer);
      case DistortionDto_Radial(
        k1: final k1,
        k2: final k2,
        k3: final k3,
        p1: final p1,
        p2: final p2,
        centerX: final centerX,
        centerY: final centerY,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_f_64(k1, serializer);
        sse_encode_f_64(k2, serializer);
        sse_encode_f_64(k3, serializer);
        sse_encode_f_64(p1, serializer);
        sse_encode_f_64(p2, serializer);
        sse_encode_opt_box_autoadd_f_64(centerX, serializer);
        sse_encode_opt_box_autoadd_f_64(centerY, serializer);
      case DistortionDto_Polynomial(
        order: final order,
        scale: final scale,
        aCoeffs: final aCoeffs,
        bCoeffs: final bCoeffs,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_u_32(order, serializer);
        sse_encode_f_64(scale, serializer);
        sse_encode_list_prim_f_64_strict(aCoeffs, serializer);
        sse_encode_list_prim_f_64_strict(bCoeffs, serializer);
    }
  }

